""" Script d'entrée unique pour lancer l'ingestion et l'application des corporate actions (équivalent à 'python -m corporate_actions run'). """ from corporate_actions.cli import _run_all, _build_parser import logging import sys
def main(): logging.basicConfig( level=logging.INFO, format="%(asctime)s %(levelname)-8s %(name)s -- %(message)s", ) parser = _build_parser() args = parser.parse_args() # Force la commande 'run' même si non précisée if not hasattr(args, 'command') or args.command != 'run': args.command = 'run' _run_all(args)
if __name__ == "__main__": main()

"""ihm/components/metrics.py — Helpers pour afficher des métriques st.metric.""" from __future__ import annotations
import streamlit as st
def metric_row(metrics: list[tuple[str, str | int | float, str | None]]) -> None: """Affiche une ligne de st.metric. Chaque tuple = (label, value, delta).""" cols = st.columns(len(metrics)) for col, (label, value, delta) in zip(cols, metrics): col.metric(label, value, delta)

"""ihm/components/status_badges.py — Badges colorés pour les statuts."""
from __future__ import annotations


def badge(label: str, status: str = "ok") -> str:
    """Retourne un emoji + label selon le statut."""
    icons = {"ok": "", "warn": "", "error": "", "info": ""}
    return f"{icons.get(status, '⚪')} {label}"


def env_badge(var_name: str, value: str | None) -> str:
    if value:
        masked = value[:4] + "****" if len(value) > 4 else "****"
        return f" `{var_name}` = `{masked}`"
    return f" `{var_name}` — **MANQUANT**"


def run_status_badge(status: str | None) -> str:
    if status is None:
        return "⚪ Inconnu"
    s = str(status).upper()
    if s in ("COMPLETED", "SUCCESS"):
        return f" {s}"
    if s == "RUNNING":
        return f" {s}"
    return f" {s}"


def decision_badge(decision: str) -> str:
    d = str(decision).upper()
    if d == "ACCEPTED":
        return " ACCEPTED"
    if d == "REDUCED":
        return " REDUCED"
    return " REJECTED"

"""ihm/components/tables.py — Helpers pour afficher des DataFrames."""
from __future__ import annotations

import pandas as pd
import streamlit as st


def show_dataframe(df: pd.DataFrame, title: str | None = None, height: int = 400) -> None:
    """Affiche un DataFrame ou un message vide."""
    if title:
        st.subheader(title)
    if df.empty:
        st.info("Aucune donnée disponible.")
    else:
        st.dataframe(df, width="stretch", height=height)

"""ihm/pages/pipeline.py — Vue séquentielle du pipeline métier.""" from __future__ import annotations
import streamlit as st
PIPELINE_STEPS = [ { "num": "1", "name": "Import Alpaca Bar", "desc": "Ingestion des barres OHLCV journalières depuis Alpaca Market Data.", "tables": "stock_bars", "cli": "python -m dataIntegrityEngine.import_alpaca_bar", "deps": "—", }, { "num": "1a", "name": "Corporate Actions Sync", "desc": "Ingestion des dividendes/splits depuis Alpaca (référentiel). Se fait AVANT le sanitizer.", "tables": "corporate_actions_events", "cli": "python -m corporate_actions sync --skip-existing", "deps": "import_alpaca_bar", }, { "num": "2", "name": "Data Sanitizer Daily", "desc": "Nettoyage, alignement calendrier, détection d'anomalies sur les barres brutes.", "tables": "stock_bars_daily, cleaning_audit_log", "cli": "python -m dataIntegrityEngine.data_sanitizer_daily", "deps": "import_alpaca_bar, corporate_actions sync", }, { "num": "3", "name": "Stock Screener", "desc": "Scores de base : liquidité 30j, force relative 6m vs SPY, range 10 ans.", "tables": "stock_scores", "cli": "python -m dataIntegrityEngine.stock_screener", "deps": "data_sanitizer_daily", }, { "num": "4", "name": "Alpha Scanner", "desc": "Scoring avancé Minervini/VCP + neutralisation sectorielle + sélection Top N.", "tables": "stock_scores (update)", "cli": "python -m selector.alpha_scanner", "deps": "stock_screener", }, { "num": "5", "name": "Sentiment Pipeline", "desc": "Ingestion news → scoring FinBERT → features ticker/secteur journalières.", "tables": "ticker_daily_sentiment_features, sector_daily_sentiment_features", "cli": "python -m event_sentiment", "deps": "alpha_scanner", }, { "num": "6", "name": "Signal Aggregator", "desc": "Fusion quant (75%) + sentiment ticker (15%) + macro sectoriel (10%) → final_score_sentiment.", "tables": "stock_scores (update final_score_sentiment)", "cli": "python -m event_sentiment.signal_aggregator", "deps": "sentiment_pipeline", }, { "num": "7", "name": "Risk Management", "desc": "Sizing ATR/Kelly, contraintes portefeuille, circuit breaker → portefeuille cible.", "tables": "risk_decisions, portfolio_targets", "cli": "python -m risk_management.run_risk --account-equity 100000", "deps": "signal_aggregator", }, { "num": "8", "name": "Execution", "desc": "Soumission ordres Alpaca (market/limit), bracket synthétique TP+TS, réconciliation, TCA.", "tables": "execution_runs, execution_orders, execution_fills, execution_events, broker_positions_snapshots", "cli": "python run_execution.py simulate # ou paper / live", "deps": "run_risk", }, { "num": "8a", "name": "Corporate Actions Apply", "desc": "Application des dividendes/splits sur les positions existantes. Se fait APRÈS l'exécution.", "tables": "corporate_actions_applications, portfolio_cash_ledger", "cli": "python -m corporate_actions apply", "deps": "run_execution", }, ]
def render() -> None: st.header(" Pipeline Quotidien") st.caption("Ordre d'exécution strict — chaque étape dépend de la précédente.")
for step in PIPELINE_STEPS: with st.expander(f"**{step['num']}. {step['name']}**", expanded=False): st.markdown(f"**Description** : {step['desc']}") st.markdown(f"**Tables impactées** : `{step['tables']}`") st.markdown(f"**Dépendances** : {step['deps']}") st.code(step["cli"], language="powershell")

"""ihm/services/db.py — Helper connexion DB pour l'IHM Streamlit."""
from __future__ import annotations

import logging
from typing import Any

import pandas as pd
import streamlit as st
from sqlalchemy import text
from sqlalchemy.engine import Engine

LOGGER = logging.getLogger(__name__)


@st.cache_resource(show_spinner=False)
def get_engine() -> Engine | None:
    """Retourne le SQLAlchemy engine, ou None si indisponible."""
    try:
        from database.connection import get_sqlalchemy_engine
        engine = get_sqlalchemy_engine()
        with engine.connect() as conn:
            conn.execute(text("SELECT 1"))
        return engine
    except Exception as exc:
        LOGGER.warning("DB indisponible : %s", exc)
        return None


def db_available() -> bool:
    return get_engine() is not None


def safe_query(query: str, params: dict[str, Any] | None = None) -> pd.DataFrame:
    """Exécute une requête SQL et retourne un DataFrame. Retourne vide si erreur."""
    engine = get_engine()
    if engine is None:
        return pd.DataFrame()
    try:
        with engine.connect() as conn:
            return pd.read_sql_query(text(query), conn, params=params or {})
    except Exception as exc:
        LOGGER.warning("Requête échouée : %s — %s", query[:80], exc)
        return pd.DataFrame()


def safe_scalar(query: str, params: dict[str, Any] | None = None) -> Any:
    """Exécute une requête qui retourne un scalaire. Retourne None si erreur."""
    engine = get_engine()
    if engine is None:
        return None
    try:
        with engine.connect() as conn:
            result = conn.execute(text(query), params or {})
            row = result.fetchone()
            return row[0] if row else None
    except Exception:
        return None

"""ihm/services/queries.py — Requêtes SQL centralisées pour l'IHM."""
from __future__ import annotations

import pandas as pd
import streamlit as st

from ihm.services.db import safe_query, safe_scalar


# ---------------------------------------------------------------------------
# Overview
# ---------------------------------------------------------------------------

@st.cache_data(ttl=60, show_spinner=False)
def get_candidates_count() -> int:
    v = safe_scalar("SELECT COUNT(*) FROM stock_scores WHERE is_candidate = 1")
    return int(v) if v is not None else 0


@st.cache_data(ttl=60, show_spinner=False)
def get_top_candidates(n: int = 10) -> pd.DataFrame:
    return safe_query(f"""
        SELECT symbol, sector, final_score_sentiment, final_score, total_score, is_candidate
        FROM stock_scores
        WHERE is_candidate = 1 AND final_score_sentiment IS NOT NULL
        ORDER BY final_score_sentiment DESC
        LIMIT {n}
    """)


@st.cache_data(ttl=60, show_spinner=False)
def get_latest_risk_run_id() -> str | None:
    v = safe_scalar("SELECT run_id FROM portfolio_targets ORDER BY created_at DESC LIMIT 1")
    return str(v) if v else None


@st.cache_data(ttl=60, show_spinner=False)
def get_latest_exec_run() -> pd.DataFrame:
    return safe_query("""
        SELECT exec_run_id, risk_run_id, trade_date, broker_mode, dry_run,
               status, started_at, completed_at, total_targets, total_submitted, total_filled, error_message
        FROM execution_runs ORDER BY started_at DESC LIMIT 1
    """)


# ---------------------------------------------------------------------------
# Screening
# ---------------------------------------------------------------------------

@st.cache_data(ttl=60, show_spinner=False)
def get_stock_scores() -> pd.DataFrame:
    return safe_query("""
        SELECT symbol, sector, is_candidate, total_score, final_score, final_score_sentiment,
               trend_score, vcp_score, signal_active, total_news,
               anomaly_count, missing_days_count,
               last_updated_score, last_updated_scan, last_updated_sentiment
        FROM stock_scores
        ORDER BY final_score_sentiment DESC, total_score DESC
    """)


# ---------------------------------------------------------------------------
# Risk
# ---------------------------------------------------------------------------

@st.cache_data(ttl=60, show_spinner=False)
def get_risk_run_ids() -> list[str]:
    df = safe_query("SELECT DISTINCT run_id FROM risk_decisions ORDER BY run_id DESC LIMIT 50")
    return df["run_id"].tolist() if not df.empty else []


@st.cache_data(ttl=60, show_spinner=False)
def get_risk_decisions(run_id: str | None = None) -> pd.DataFrame:
    if run_id:
        return safe_query("""
            SELECT * FROM risk_decisions WHERE run_id = :run_id ORDER BY created_at DESC
        """, {"run_id": run_id})
    return safe_query("SELECT * FROM risk_decisions ORDER BY created_at DESC LIMIT 200")


@st.cache_data(ttl=60, show_spinner=False)
def get_portfolio_targets(run_id: str | None = None) -> pd.DataFrame:
    if run_id:
        return safe_query("""
            SELECT * FROM portfolio_targets WHERE run_id = :run_id ORDER BY target_weight DESC
        """, {"run_id": run_id})
    return safe_query("""
        SELECT * FROM portfolio_targets
        WHERE run_id = (SELECT run_id FROM portfolio_targets ORDER BY created_at DESC LIMIT 1)
        ORDER BY target_weight DESC
    """)


# ---------------------------------------------------------------------------
# Execution
# ---------------------------------------------------------------------------

@st.cache_data(ttl=60, show_spinner=False)
def get_execution_runs(limit: int = 20) -> pd.DataFrame:
    return safe_query(f"""
        SELECT exec_run_id, risk_run_id, trade_date, broker_mode, dry_run,
               status, started_at, completed_at, total_targets, total_submitted,
               total_filled, error_message
        FROM execution_runs ORDER BY started_at DESC LIMIT {limit}
    """)


@st.cache_data(ttl=60, show_spinner=False)
def get_execution_events(exec_run_id: str | None = None) -> pd.DataFrame:
    if exec_run_id:
        return safe_query("""
            SELECT event_type, symbol, message, created_at
            FROM execution_events WHERE exec_run_id = :eid ORDER BY created_at DESC
        """, {"eid": exec_run_id})
    return safe_query("SELECT event_type, symbol, message, created_at FROM execution_events ORDER BY created_at DESC LIMIT 100")


@st.cache_data(ttl=60, show_spinner=False)
def get_broker_positions() -> pd.DataFrame:
    return safe_query("""
        SELECT bps.* FROM broker_positions_snapshots bps
        INNER JOIN (SELECT MAX(created_at) AS mx FROM broker_positions_snapshots) t ON bps.created_at = t.mx
        ORDER BY market_value DESC
    """)


@st.cache_data(ttl=60, show_spinner=False)
def get_execution_fills(exec_run_id: str | None = None) -> pd.DataFrame:
    if exec_run_id:
        return safe_query("""
            SELECT * FROM execution_fills WHERE exec_run_id = :eid ORDER BY fill_timestamp DESC
        """, {"eid": exec_run_id})
    return safe_query("SELECT * FROM execution_fills ORDER BY fill_timestamp DESC LIMIT 100")


# ---------------------------------------------------------------------------
# Corporate Actions
# ---------------------------------------------------------------------------

@st.cache_data(ttl=60, show_spinner=False)
def get_ca_events_summary() -> pd.DataFrame:
    return safe_query("""
        SELECT status, ca_type, COUNT(*) as cnt
        FROM corporate_actions_events GROUP BY status, ca_type ORDER BY status, ca_type
    """)


@st.cache_data(ttl=60, show_spinner=False)
def get_ca_events(limit: int = 100) -> pd.DataFrame:
    return safe_query(f"SELECT * FROM corporate_actions_events ORDER BY ex_date DESC LIMIT {limit}")


@st.cache_data(ttl=60, show_spinner=False)
def get_ca_applications(limit: int = 50) -> pd.DataFrame:
    return safe_query(f"SELECT * FROM corporate_actions_applications ORDER BY applied_at DESC LIMIT {limit}")


@st.cache_data(ttl=60, show_spinner=False)
def get_total_dividends() -> float:
    v = safe_scalar("SELECT COALESCE(SUM(amount), 0) FROM portfolio_cash_ledger WHERE entry_type = 'dividend_credit'")
    return float(v) if v is not None else 0.0


# ---------------------------------------------------------------------------
# ML
# ---------------------------------------------------------------------------

@st.cache_data(ttl=60, show_spinner=False)
def get_training_runs(limit: int = 20) -> pd.DataFrame:
    return safe_query(f"SELECT * FROM model_training_run ORDER BY started_at DESC LIMIT {limit}")


@st.cache_data(ttl=60, show_spinner=False)
def get_model_metrics() -> pd.DataFrame:
    return safe_query("SELECT * FROM model_metrics ORDER BY symbol, split_name")


@st.cache_data(ttl=60, show_spinner=False)
def get_predictions(limit: int = 100) -> pd.DataFrame:
    return safe_query(f"""
        SELECT symbol, predicted_proba, predicted_class, prediction_date, run_id, created_at
        FROM model_predictions ORDER BY prediction_date DESC, symbol LIMIT {limit}
    """)
